[{"order":1,"type":"heading","text":"Mastering Svelte Stores: Writable, Readable, and Derived"},{"order":2,"type":"paragraph","text":"State management in Svelte is built around stores. A store is simply an object with a 'subscribe' method that allows interested parties to be notified when the store's value changes. Svelte provides three main types of stores out of the box: Writable, Readable, and Derived."},{"order":3,"type":"subheading","text":"1. Writable Stores"},{"order":4,"type":"paragraph","text":"Writable stores are stores that can be updated from both inside and outside components. They are created using the 'writable' function from 'svelte/store'. They expose three methods: 'set', 'update', and 'subscribe'."},{"order":5,"type":"code","text":"import { writable } from 'svelte/store';

// Initialize with a default value
export const count = writable(0);

// Updating a writable store
function increment() {
    count.update(n => n + 1);
}

function reset() {
    count.set(0);
}"},{"order":6,"type":"subheading","text":"2. Readable Stores"},{"order":7,"type":"paragraph","text":"Sometimes you want a store whose value cannot be modified from the outside. A common use case is a store that tracks the current time or geolocation. Readable stores take a start function as their first argument."},{"order":8,"type":"code","text":"import { readable } from 'svelte/store';

export const time = readable(new Date(), (set) => {
    const interval = setInterval(() => {
        set(new Date());
    }, 1000);

    return () => clearInterval(interval);
});"},{"order":9,"type":"subheading","text":"3. Derived Stores"},{"order":10,"type":"paragraph","text":"Derived stores allow you to create a new store whose value depends on the value of one or more other stores. This is extremely useful for computed state, filtering lists, or formatting data."},{"order":11,"type":"code","text":"import { writable, derived } from 'svelte/store';

export const count = writable(3);

// Derived store calculating the square of count
export const squared = derived(count, $count => $count * $count);"},{"order":12,"type":"subheading","text":"Using Stores in Svelte Components"},{"order":13,"type":"paragraph","text":"To read a store value inside a Svelte component, you can prefix the store name with a dollar sign ('$'). This is known as auto-subscription. Svelte handles subscribing and unsubscribing under the hood automatically."},{"order":14,"type":"code","text":"<script>
    import { count, squared } from './stores.js';

    function handleClick() {
        count.update(n => n + 1);
    }
</script>

<button on:click="{handleClick}">
    Clicks: {$count}, Squared: {$squared}
</button>"},{"order":15,"type":"bullet_point","text":"Writable stores allow full read and write access using set() and update()."},{"order":16,"type":"bullet_point","text":"Readable stores are controlled entirely by their producer function and protect state from external mutations."},{"order":17,"type":"bullet_point","text":"Derived stores compute new values automatically when their parent stores change."},{"order":18,"type":"bullet_point","text":"Always use the '$' auto-subscription prefix inside Svelte component markup and script tags for clean, memory-leak-free code."}]
